rt_fields(section_id,field_key,label,field_type,placeholder,help_text,options_json,default_value,linked_source_key,is_required,sort_order,active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())',$data);$record=(int)Database::lastInsertId();}ManagementReportsRepository::bumpTemplateVersion((int)$template['id']);$message='فیلد گزارش در نسخه جدید قالب ذخیره شد.';}
